#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
int LLVMFuzzerTestOneInput(const uint8_t*, size_t);
static int run_data(const unsigned char* data, size_t n){ unsigned char* p=(unsigned char*)malloc(n?n:1); if(!p) return 2; if(n) memcpy(p,data,n); int r=LLVMFuzzerTestOneInput(p,n); free(p); return r; }
static int run_file(FILE* f){ unsigned char* p=NULL; size_t n=0,cap=0,got; unsigned char tmp[4096]; while((got=fread(tmp,1,sizeof(tmp),f))>0){ if(n+got>cap){ size_t nc=cap?cap*2:4096; while(n+got>nc) nc*=2; unsigned char*q=(unsigned char*)realloc(p,nc); if(!q) return 2; p=q; cap=nc;} memcpy(p+n,tmp,got); n+=got;} int r=LLVMFuzzerTestOneInput(p,n); free(p); return r; }
int main(int argc, char** argv) {
    if(argc >= 2) { FILE* f=fopen(argv[1],"rb"); if(f){ int r=run_file(f); fclose(f); return r; } }
    if(argc < 2) return run_file(stdin);
    static const unsigned char fallback[] = {0x00,0x00,0x08,0x00,0,0,0,0,0x66,0x6f,0x6f,0x0a,0x3e,0x5b,0x21,0x74,0x69,0x70,0x5d,0x0a,0x3e,0x2d,0x0a};
    return run_data(fallback, sizeof(fallback));
}
